<?php require 'includes/functions.php';require_login();$pdo=db();$uid=user()['id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['action']??'')==='add'){$pdo->prepare('INSERT INTO addresses(user_id,full_name,mobile,address,city,state,pincode,is_default) VALUES(?,?,?,?,?,?,?,?)')->execute([$uid,trim($_POST['full_name']),trim($_POST['mobile']),trim($_POST['address']),trim($_POST['city']),trim($_POST['state']),trim($_POST['pincode']),empty($_POST['default'])?0:1]);if(!empty($_POST['default']))$pdo->prepare('UPDATE addresses SET is_default=0 WHERE user_id=? AND id!=?')->execute([$uid,$pdo->lastInsertId()]);flash('success','Address saved.');}go('addresses.php');}if(($_GET['action']??'')==='delete'){$pdo->prepare('DELETE FROM addresses WHERE id=? AND user_id=?')->execute([(int)$_GET['id'],$uid]);flash('success','Address removed.');go('addresses.php');}$q=$pdo->prepare('SELECT * FROM addresses WHERE user_id=? ORDER BY is_default DESC,id DESC');$q->execute([$uid]);$addresses=$q->fetchAll();$pageTitle='Addresses';require 'includes/header.php';require 'includes/navbar.php'; ?>
<main class="container my-5"><h1 class="section-title">My addresses</h1><div class="row g-3"><?php foreach($addresses as $a): ?><div class="col-md-4"><div class="card card-body h-100"><b><?=e($a['full_name'])?> <?=$a['is_default']?'<span class="badge text-bg-dark">Default</span>':''?></b><small><?=e($a['mobile'])?></small><p class="mt-2 mb-2"><?=e($a['address'])?><br><?=e($a['city'])?>, <?=e($a['state'])?> - <?=e($a['pincode'])?></p><a class="text-danger" href="<?=base('addresses.php?action=delete&id='.$a['id'])?>" data-confirm="Remove this address?">Remove</a></div></div><?php endforeach ?></div><form method="post" class="card card-body mt-4"><input type="hidden" name="action" value="add"><h5>Add new address</h5><div class="row g-2"><div class="col-md-6"><input class="form-control" name="full_name" placeholder="Full name" required></div><div class="col-md-6"><input class="form-control" name="mobile" placeholder="Mobile" required></div><div class="col-12"><textarea class="form-control" name="address" placeholder="Address" required></textarea></div><div class="col-md"><input class="form-control" name="city" placeholder="City" required></div><div class="col-md"><input class="form-control" name="state" placeholder="State" required></div><div class="col-md"><input class="form-control" name="pincode" placeholder="Pincode" required></div><div class="col-12"><label><input type="checkbox" name="default"> Set as default address</label></div><div><button class="btn btn-dark">Save address</button></div></div></form></main><?php require 'includes/footer.php'; ?>
